import csv
from datetime import datetime

def main():
    input_file = 'bookstore_orders.csv'
    output_file = 'carrier-otd.csv'

    # dict: carrier -> {'total':0, 'ontime':0}
    stats = {}

    with open(input_file, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            # Filter delivered orders
            if row['fulfillment_status'].strip().lower() != 'delivered':
                continue
            carrier = row['carrier_name'].strip()
            if not carrier:
                carrier = 'Unknown'
            est_str = row['estimated_delivery_date'].strip()
            act_str = row['actual_delivery_date'].strip()
            # If missing dates, treat as not on-time? We'll skip if missing.
            if not est_str or not act_str:
                # Still count as delivered but not on-time
                if carrier not in stats:
                    stats[carrier] = {'total':0, 'ontime':0}
                stats[carrier]['total'] += 1
                continue
            try:
                est_date = datetime.strptime(est_str, '%Y-%m-%d').date()
                act_date = datetime.strptime(act_str, '%Y-%m-%d').date()
            except ValueError:
                # If parsing fails, treat as not on-time
                if carrier not in stats:
                    stats[carrier] = {'total':0, 'ontime':0}
                stats[carrier]['total'] += 1
                continue
            # Update stats
            if carrier not in stats:
                stats[carrier] = {'total':0, 'ontime':0}
            stats[carrier]['total'] += 1
            if act_date <= est_date:
                stats[carrier]['ontime'] += 1

    # Prepare rows
    rows = []
    for carrier, data in stats.items():
        total = data['total']
        ontime = data['ontime']
        if total == 0:
            pct = 0.0
        else:
            pct = (ontime / total) * 100.0
        rows.append({
            'CarrierName': carrier,
            'TotalDelivered': total,
            'OnTimeDelivered': ontime,
            'OnTimePct': round(pct, 2)
        })

    # Sort by OnTimePct descending
    rows.sort(key=lambda x: x['OnTimePct'], reverse=True)

    # Write CSV
    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        fieldnames = ['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct']
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for r in rows:
            writer.writerow(r)

    print(f"Written carrier on-time delivery to {output_file}")

if __name__ == '__main__':
    main()

