def main():
    input_file = 'bookstore_orders.csv'
    output_file = 'carrier-otd.csv'

    stats = {}

    with open(input_file, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['fulfillment_status'].strip().lower() != 'delivered':
                continue
            carrier = row['carrier_name'].strip()
            if not carrier:
                carrier = 'Unknown'
            est_str = row['estimated_delivery_date'].strip()
            act_str = row['actual_delivery_date'].strip()
            if not est_str or not act_str:
                if carrier not in stats:
                    stats[carrier] = {'total':0, 'ontime':0}
                stats[carrier]['total'] += 1
                continue
            try:
                est_date = datetime.strptime(est_str, '%Y-%m-%d').date()
                # actual may have timestamp; split
                act_date_str = act_str.split()[0]  # take date part
                act_date = datetime.strptime(act_date_str, '%Y-%m-%d').date()
            except ValueError:
                if carrier not in stats:
                    stats[carrier] = {'total':0, 'ontime':0}
                stats[carrier]['total'] += 1
                continue
            if carrier not in stats:
                stats[carrier] = {'total':0, 'ontime':0}
            stats[carrier]['total'] += 1
            if act_date <= est_date:
                stats[carrier]['ontime'] += 1

    rows = []
    for carrier, data in stats.items():
        total = data['total']
        ontime = data['ontime']
        pct = (ontime / total * 100.0) if total else 0.0
        rows.append({
            'CarrierName': carrier,
            'TotalDelivered': total,
            'OnTimeDelivered': ontime,
            'OnTimePct': round(pct, 2)
        })

    rows.sort(key=lambda x: x['OnTimePct'], reverse=True)

    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        fieldnames = ['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct']
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for r in rows:
            writer.writerow(r)

    print(f"Written carrier on-time delivery to {output_file}")

if __name__ == '__main__':
    main()

import csv
from datetime import datetime

def main():
    input_file = 'bookstore_orders.csv'
    output_file = 'carrier-delivery-time.csv'

    # dict: carrier -> {'total_hours':0.0, 'count':0}
    stats = {}

    with open(input_file, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['fulfillment_status'].strip().lower() != 'delivered':
                continue
            carrier = row['carrier_name'].strip()
            if not carrier:
                carrier = 'Unknown'
            order_ts = row['order_timestamp'].strip()
            actual_ts = row['actual_delivery_date'].strip()
            if not order_ts or not actual_ts:
                # skip if missing timestamp
                continue
            try:
                # order_timestamp format: '2025-06-13 11:01:00'
                order_dt = datetime.strptime(order_ts, '%Y-%m-%d %H:%M:%S')
                # actual_delivery_date may have timestamp; we'll try same format
                actual_dt = datetime.strptime(actual_ts, '%Y-%m-%d %H:%M:%S')
            except ValueError:
                # if actual_delivery_date only has date? but from sample includes time.
                # try parsing date only
                try:
                    order_dt = datetime.strptime(order_ts, '%Y-%m-%d %H:%M:%S')
                    actual_dt = datetime.strptime(actual_ts.split()[0], '%Y-%m-%d')
                except ValueError:
                    continue
            # compute difference in hours
            diff = actual_dt - order_dt
            hours = diff.total_seconds() / 3600.0
            if hours < 0:
                # negative? maybe actual before order? skip or treat as zero? We'll skip.
                continue
            if carrier not in stats:
                stats[carrier] = {'total_hours':0.0, 'count':0}
            stats[carrier]['total_hours'] += hours
            stats[carrier]['count'] += 1

    rows = []
    for carrier, data in stats.items():
        count = data['count']
        if count == 0:
            avg = 0.0
        else:
            avg = data['total_hours'] / count
        rows.append({
            'CarrierName': carrier,
            'DeliveredOrders': count,
            'AvgDeliveryHours': round(avg, 2)
        })

    # Sort by AvgDeliveryHours ascending (fastest first)
    rows.sort(key=lambda x: x['AvgDeliveryHours'])

    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        fieldnames = ['CarrierName', 'DeliveredOrders', 'AvgDeliveryHours']
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for r in rows:
            writer.writerow(r)

    print(f"Written carrier delivery times to {output_file}")

if __name__ == '__main__':
    main()

