fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) {
        return "0s"
    }
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 1.0) {
        // Format to remove trailing zeros
        val formatted = "%.3f".format(seconds).replace(Regex("\\.0+$"), "")
        "$formatteds"
    } else {
        val denominator = 1.0 / seconds
        val denomInt = denominator.roundToInt()
        // Check if we can represent as a fraction 1/denomInt with acceptable error (3%)
        val error = Math.abs(denominator - denomInt) / denominator
        if (error < 0.03 && denomInt >= 2 && denomInt <= 10000) {
            "1/$denomInts"
        } else {
            val formatted = "%.3f".format(seconds).replace(Regex("\\.0+$"), "")
            "$formatteds"
        }
    }
}

