def legal_moves(fen: str) -> list[str]:
    """Return list of legal moves in UCI notation for side to move.
    Normal piece movement, captures, pawn double pushes only.
    No castling, en passant, promotion, or check/pin legality."""
    board, side_to_move = _parse_fen(fen)
    moves = []
    for sq in range(64):
        piece = board[sq]
        if piece == '.':
            continue
        is_white = piece.isupper()
        if (is_white and side_to_move == 'w') or (not is_white and side_to_move == 'b'):
            # generate moves based on piece type
            piece_lower = piece.lower()
            if piece_lower == 'p':
                moves.extend(_pawn_moves(board, sq, is_white))
            elif piece_lower == 'n':
                moves.extend(_knight_moves(board, sq, is_white))
            elif piece_lower == 'b':
                moves.extend(_slider_moves(board, sq, is_white, _BISHOP_DIRS))
            elif piece_lower == 'r':
                moves.extend(_slider_moves(board, sq, is_white, _ROOK_DIRS))
            elif piece_lower == 'q':
                moves.extend(_slider_moves(board, sq, is_white, _QUEEN_DIRS))
            elif piece_lower == 'k':
                moves.extend(_king_moves(board, sq, is_white))
    # convert moves to UCI strings
    return [_move_to_uci(m) for m in moves]


def perft(fen: str, depth: int) -> int:
    """Return number of leaf nodes at given depth.
    perft(0) == 1."""
    if depth < 0:
        raise ValueError("depth must be non-negative")
    pos = _Position.from_fen(fen)
    return _perft(pos, depth)


# -------------------- internal helpers --------------------

# Directions for sliding pieces
_NORTH = 8
_SOUTH = -8
_EAST = 1
_WEST = -1
_NORTHEAST = _NORTH + _EAST
_NORTHWEST = _NORTH + _WEST
_SOUTHEAST = _SOUTH + _EAST
_SOUTHWEST = _SOUTH + _WEST

_BISHOP_DIRS = [_NORTHEAST, _NORTHWEST, _SOUTHEAST, _SOUTHWEST]
_ROOK_DIRS = [_NORTH, _SOUTH, _EAST, _WEST]
_QUEEN_DIRS = _BISHOP_DIRS + _ROOK_DIRS

_KNIGHT_OFFSETS = [
    _NORTHEAST + _EAST,  # 2N+E
    _NORTHEAST + _NORTH, # 2N+W? wait compute later
]
# Actually compute properly:
_KNIGHT_OFFSETS = [
    _NORTH + _NORTH + _EAST,
    _NORTH + _NORTH + _WEST,
    _SOUTH + _SOUTH + _EAST,
    _SOUTH + _SOUTH + _WEST,
    _EAST + _EAST + _NORTH,
    _EAST + _EAST + _SOUTH,
    _WEST + _WEST + _NORTH,
    _WEST + _WEST + _SOUTH,
