    'w': [_NORTHEAST, _NORTHWEST],
    'b': [_SOUTHEAST, _SOUTHWEST],
}


def _parse_fen(fen: str):
    """Parse board and side to move from FEN."""
    parts = fen.split()
    board_part = parts[0]
    side = parts[1] if len(parts) > 1 else 'w'
    board = []
    for rank in board_part.split('/'):
        for ch in rank:
            if ch.isdigit():
                board.extend(['.'] * int(ch))
            else:
                board.append(ch)
    # board[0] = a1, board[63] = h8
    return board, side


def _move_to_uci(move):
    src, dst = move
    return _square_to_coord(src) + _square_to_coord(dst)


def _square_to_coord(sq):
    file = sq % 8
    rank = sq // 8
    return chr(ord('a') + file) + str(rank + 1)


def _coord_to_square(coord: str) -> int:
    file = ord(coord[0]) - ord('a')
    rank = int(coord[1]) - 1
    return rank * 8 + file


