def _pawn_moves(board, sq, is_white):
    color = 'w' if is_white else 'b'
    forward = _PASSIVE_PAWN_OFFSETS[color]
    captures = _PAWN_CAPTURE_OFFSETS[color]
    moves = []
    # one step forward
    one = sq + forward[0]
    if 0 <= one < 64 and board[one] == '.':
        moves.append((sq, one))
