class _Position:
    __slots__ = ('board', 'side', 'castling', 'enpassant', 'halfmove', 'fullmove')

    def __init__(self, board, side, castling='-', enpassant='-', halfmove=0, fullmove=1):
        self.board = board  # list of 64 chars
        self.side = side    # 'w' or 'b'
        self.castling = castling
        self.enpassant = enpassant
        self.halfmove = halfmove
        self.fullmove = fullmove

    @classmethod
    def from_fen(cls, fen: str):
        parts = fen.split()
        board_part = parts[0]
        side = parts[1] if len(parts) > 1 else 'w'
        castling = parts[2] if len(parts) > 2 else '-'
        enpassant = parts[3] if len(parts) > 3 else '-'
        halfmove = int(parts[4]) if len(parts) > 4 else 0
        fullmove = int(parts[5]) if len(parts) > 5 else 1
        board = []
        for rank in board_part.split('/'):
            for ch in rank:
                if ch.isdigit():
                    board.extend(['.'] * int(ch))
                else:
                    board.append(ch)
        return cls(board, side, castling, enpassant, halfmove, fullmove)

    def make_move(self, move):
        src, dst = move
        piece = self.board[src]
        captured = self.board[dst]
        # move piece
        self.board[dst] = piece
        self.board[src] = '.'
        # swap side
        self.side = 'b' if self.side == 'w' else 'w'
        # For simplicity we don't update castling/enpassant etc.
        # Return info needed to unmake
        return (src, dst, piece, captured)

    def unmake_move(self, move, info):
        src, dst, piece, captured = info
        # restore board
        self.board[src] = piece
        self.board[dst] = captured
        # swap side back
        self.side = 'b' if self.side == 'w' else 'w'


def _perft(pos: _Position, depth: int) -> int:
    if depth == 0:
        return 1
    total = 0
    moves = _generate_moves(pos)
    for mv in moves:
        info = pos.make_move(mv)
        total += _perft(pos, depth - 1)
        pos.unmake_move(mv, info)
    return total


